struct MoneyTag: LeafTag {
    func render(_ ctx: LeafContext) throws -> LeafData {
        guard let raw = ctx.parameters.first?.string, let cents = Int(raw) else {
            throw Abort(.badRequest, reason: "money expects integer cents")
        }
        let f = NumberFormatter()
        f.numberStyle = .currency
        f.currencyCode = ctx.data["currency"]?.string ?? "EUR"
        return LeafData.string(f.string(from: NSNumber(value: Double(cents) / 100)) ?? "")
    }
}
// configure.swift:  app.leaf.tags["money"] = MoneyTag()      // view:  #money(order.total)
